"use strict";
// Loads a module whose name is only known when the program runs: scriptc
// cannot compile that natively, so the package runs in a Node island.
const os = require(process.env.ISLANDSTRINGS_OS_MODULE || "node:os");

exports.eol = os.EOL.length;
// A one-byte (Latin-1) string: the engine stores it as the bytes FF and the tail.
exports.oneByte = (tail) => String.fromCharCode(0xff) + tail;
exports.decoded = (tail) => Buffer.from([0xff, tail]).toString("latin1");
exports.lone = () => "\ud800n";
exports.pair = () => "\ud83d" + "\ude00";
exports.keys = () => Object.keys({ "ÿn": 1, "ÿu": 2 });
exports.list = () => ["ÿn", "ÿu", "\udfff"];
exports.fail = () => {
  throw new Error("ÿn");
};
exports.call = (callback) => {
  callback("ÿn");
  callback("ÿu");
};
exports.table = () => new Map([["ÿn", "ÿu"]]);
